    }

pub fn readVerbatimString(self: *ValkeyReader, allocator: std.mem.Allocator) RedisError!VerbatimString {
            const len = try self.readInteger();
            if ((len < 0)) {
                return error.InvalidVerbatimString;
            }
            const ulen = (if (comptime @typeInfo(@TypeOf(len)) == .@"enum") cp_cast_int(usize, @intFromEnum(len)) else cp_cast_int(usize, len));
            if (((self.pos + ulen) > self.buffer.len)) {
                return error.InvalidVerbatimString;
            }
            const content_with_format = self.buffer[self.pos..(self.pos + ulen)];
            self.pos = (self.pos + ulen);
            const crlf = try self.readUntilCRLF();
            if ((crlf.len != 0)) {
                return error.InvalidVerbatimString;
            }
            if (((content_with_format.len < 4) or (content_with_format[3] != 58))) {
                return error.InvalidVerbatimString;
            }
            const format = try allocator.dupe(u8, content_with_format[0..3]);
            const content = try allocator.dupe(u8, content_with_format[4..]);
            return VerbatimString{ .format = format, .content = content };
    }

pub fn readValue(self: *ValkeyReader, allocator: std.mem.Allocator) RedisError!RESPValue {
            return self.readValueWithDepth(allocator, 0);
    }

pub fn readValueWithDepth(self: *ValkeyReader, allocator: std.mem.Allocator, depth: usize) RedisError!RESPValue {
            const type_byte = try self.readByte();
            const resp_type_opt = RESPType.fromByte(type_byte);
            if ((resp_type_opt == null)) {
                return error.InvalidResponseType;
            }
            const resp_type = resp_type_opt.?;
            return (switch (resp_type) {
.SimpleString => {
{
                const str = try self.readUntilCRLF();
                const owned = try allocator.dupe(u8, str);
                return RESPValue{ .SimpleString = owned };
            }
},
.Error => {
{
                const str = try self.readUntilCRLF();
                const owned = try allocator.dupe(u8, str);
                return RESPValue{ .Error = owned };
            }
},
.Integer => {
{
                const int = try self.readInteger();
                return RESPValue{ .Integer = int };
            }
},
.BulkString => {
{
                const len = try self.readInteger();
                if ((len < 0)) {
                    return RESPValue{ .BulkString = null };
                }
                const ulen = (if (comptime @typeInfo(@TypeOf(len)) == .@"enum") cp_cast_int(usize, @intFromEnum(len)) else cp_cast_int(usize, len));
                if (((self.pos + ulen) > self.buffer.len)) {
                    return error.InvalidResponse;
                }
                const str = self.buffer[self.pos..(self.pos + ulen)];
                self.pos = (self.pos + ulen);
                const crlf = try self.readUntilCRLF();
                if ((crlf.len != 0)) {
                    return error.InvalidBulkString;
                }
                const owned = try allocator.dupe(u8, str);
                return RESPValue{ .BulkString = owned };
            }
},
.Array => {
{
                if ((depth >= max_nesting_depth)) {
                    return error.NestingDepthExceeded;
                }
                const len = try self.readInteger();
                if ((len < 0)) {
                    return RESPValue{ .Array = empty_resp_array };
                }
                var array = try allocator.alloc(RESPValue, (if (comptime @typeInfo(@TypeOf(len)) == .@"enum") cp_cast_int(usize, @intFromEnum(len)) else cp_cast_int(usize, len)));
                _ = &array;
                errdefer {
                _ = allocator.free(array);
                }
                var i: usize = 0;
                _ = &i;
                errdefer {
                {
                    var j: usize = 0;
                    _ = &j;
                    while ((j < i)) : (j = (j + 1)) {
                        _ = array[@as(usize, @intCast(j))].deinit(allocator);
                    }
                }
                }
                const ulen = (if (comptime @typeInfo(@TypeOf(len)) == .@"enum") cp_cast_int(usize, @intFromEnum(len)) else cp_cast_int(usize, len));
                while ((i < ulen)) : (i = (i + 1)) {
                    array[cp_cast_int(usize, i)] = try self.readValueWithDepth(allocator, (depth + 1));
                }
                return RESPValue{ .Array = array };
            }
},
.Null => {
{
                _ = try self.readUntilCRLF();
                return null_resp_value;
            }
},
.Double => {
{
                const d = try self.readDouble();
                return RESPValue{ .Double = d };
            }
},
.Boolean => {
{
                const b = try self.readBoolean();
                return RESPValue{ .Boolean = b };
            }
},
.BlobError => {
{
                const len = try self.readInteger();
                if ((len < 0)) {
                    return error.InvalidBlobError;
                }
                const ulen = (if (comptime @typeInfo(@TypeOf(len)) == .@"enum") cp_cast_int(usize, @intFromEnum(len)) else cp_cast_int(usize, len));
                if (((self.pos + ulen) > self.buffer.len)) {
                    return error.InvalidBlobError;
                }
                const str = self.buffer[self.pos..(self.pos + ulen)];
                self.pos = (self.pos + ulen);
                const crlf = try self.readUntilCRLF();
                if ((crlf.len != 0)) {
                    return error.InvalidBlobError;
                }
                const owned = try allocator.dupe(u8, str);
                return RESPValue{ .BlobError = owned };
            }
},
.VerbatimString => {
return RESPValue{ .VerbatimString = try self.readVerbatimString(allocator) };
},
.Map => {
{
                if ((depth >= max_nesting_depth)) {
                    return error.NestingDepthExceeded;
                }
                const len = try self.readInteger();
                if ((len < 0)) {
                    return error.InvalidMap;
                }
                const ulen = (if (comptime @typeInfo(@TypeOf(len)) == .@"enum") cp_cast_int(usize, @intFromEnum(len)) else cp_cast_int(usize, len));
                var entries = try allocator.alloc(MapEntry, ulen);
                _ = &entries;
                errdefer {
                _ = allocator.free(entries);
                }
                var i: usize = 0;
                _ = &i;
                errdefer {
                {
                    var j: usize = 0;
                    _ = &j;
                    while ((j < i)) : (j = (j + 1)) {
                        _ = entries[@as(usize, @intCast(j))].deinit(allocator);
                    }
                }
                }
                while ((i < ulen)) : (i = (i + 1)) {
                    var key = try self.readValueWithDepth(allocator, (depth + 1));
                    _ = &key;
                    errdefer {
                    _ = key.deinit(allocator);
                    }
                    const value = try self.readValueWithDepth(allocator, (depth + 1));
                    entries[cp_cast_int(usize, i)] = MapEntry{ .key = key, .value = value };
                }
                return RESPValue{ .Map = entries };
            }
},
.Set => {
{
                if ((depth >= max_nesting_depth)) {
                    return error.NestingDepthExceeded;
                }
                const len = try self.readInteger();
                if ((len < 0)) {
                    return error.InvalidSet;
                }
                const ulen = (if (comptime @typeInfo(@TypeOf(len)) == .@"enum") cp_cast_int(usize, @intFromEnum(len)) else cp_cast_int(usize, len));
                var set = try allocator.alloc(RESPValue, ulen);
                _ = &set;
                errdefer {
                _ = allocator.free(set);
                }
                var i: usize = 0;
                _ = &i;
                errdefer {
                {
                    var j: usize = 0;
                    _ = &j;
                    while ((j < i)) : (j = (j + 1)) {
                        _ = set[@as(usize, @intCast(j))].deinit(allocator);
                    }
                }
                }
                while ((i < ulen)) : (i = (i + 1)) {
                    set[cp_cast_int(usize, i)] = try self.readValueWithDepth(allocator, (depth + 1));
                }
                return RESPValue{ .Set = set };
            }
},
.Attribute => {
{
                if ((depth >= max_nesting_depth)) {
                    return error.NestingDepthExceeded;
                }
                const len = try self.readInteger();
                if ((len < 0)) {
                    return error.InvalidAttribute;
                }
                const ulen = (if (comptime @typeInfo(@TypeOf(len)) == .@"enum") cp_cast_int(usize, @intFromEnum(len)) else cp_cast_int(usize, len));
                var attrs = try allocator.alloc(MapEntry, ulen);
                _ = &attrs;
                errdefer {
                _ = allocator.free(attrs);
                }
                var i: usize = 0;
                _ = &i;
                errdefer {
                {
                    var j: usize = 0;
                    _ = &j;
                    while ((j < i)) : (j = (j + 1)) {
                        _ = attrs[@as(usize, @intCast(j))].deinit(allocator);
                    }
                }
                }
                while ((i < ulen)) : (i = (i + 1)) {
                    var key = try self.readValueWithDepth(allocator, (depth + 1));
                    _ = &key;
                    errdefer {
                    _ = key.deinit(allocator);
                    }
                    const value = try self.readValueWithDepth(allocator, (depth + 1));
                    attrs[cp_cast_int(usize, i)] = MapEntry{ .key = key, .value = value };
                }
                var value_ptr = try allocator.create(RESPValue);
                _ = &value_ptr;
                errdefer {
                {
                    _ = allocator.destroy(value_ptr);
                }
                }
                {
                    value_ptr.* = try self.readValueWithDepth(allocator, (depth + 1));
                }
                return RESPValue{ .Attribute = Attribute{ .attributes = attrs, .value = value_ptr } };
            }
},
.Push => {
{
                if ((depth >= max_nesting_depth)) {
                    return error.NestingDepthExceeded;
                }
                const len = try self.readInteger();
                if ((len <= 0)) {
                    return error.InvalidPush;
                }
                var push_type = try self.readValueWithDepth(allocator, (depth + 1));
                _ = &push_type;
                defer {
                _ = push_type.deinit(allocator);
                }
                var push_type_str: []const u8 = "";
                _ = &push_type_str;
                switch (push_type) {
.SimpleString => |str| {
push_type_str = str;
},
.BulkString => |maybe_str| {
if (maybe_str) |str| {
                    _ = &str;
                    push_type_str = str;
                } else {
                    return error.InvalidPush;
                }
},
else => {
return error.InvalidPush;
},
}
                const push_type_dup = try allocator.dupe(u8, push_type_str);
                errdefer {
                _ = allocator.free(push_type_dup);
                }
                const ulen = (if (comptime @typeInfo(@TypeOf((len - 1))) == .@"enum") cp_cast_int(usize, @intFromEnum((len - 1))) else cp_cast_int(usize, (len - 1)));
                var data = try allocator.alloc(RESPValue, ulen);
                _ = &data;
                errdefer {
                _ = allocator.free(data);
                }
                var i: usize = 0;
                _ = &i;
                errdefer {
                {
                    var j: usize = 0;
                    _ = &j;
                    while ((j < i)) : (j = (j + 1)) {
                        _ = data[@as(usize, @intCast(j))].deinit(allocator);
                    }
                }
                }
                while ((i < ulen)) : (i = (i + 1)) {
                    data[cp_cast_int(usize, i)] = try self.readValueWithDepth(allocator, (depth + 1));
                }
                return RESPValue{ .Push = Push{ .kind = push_type_dup, .data = data } };
            }
},
.BigNumber => {
{
                const str = try self.readUntilCRLF();
                const owned = try allocator.dupe(u8, str);
                return RESPValue{ .BigNumber = owned };
            }
},
});
    }
};

pub const MapEntry = struct {
    key: RESPValue,
    value: RESPValue,

pub fn deinit(self: *MapEntry, allocator: std.mem.Allocator) void {
            _ = self.key.deinit(allocator);
            _ = self.value.deinit(allocator);
    }
};

pub const VerbatimString = struct {
    format: []const u8,
    content: []const u8,

pub fn deinit(self: *VerbatimString, allocator: std.mem.Allocator) void {
            _ = allocator.free(self.format);
            _ = allocator.free(self.content);
    }
};

pub const Push = struct {
    kind: []const u8,
    data: []RESPValue,

pub fn deinit(self: *Push, allocator: std.mem.Allocator) void {
            _ = allocator.free(self.kind);
            for (cp_mut_slice(&self.data)) |*item| {
                _ = &item;
                _ = (item.*).deinit(allocator);
            }
            _ = allocator.free(self.data);
    }
};

pub const Attribute = struct {
    attributes: []MapEntry,
    value: *RESPValue,

pub fn deinit(self: *Attribute, allocator: std.mem.Allocator) void {
            for (cp_mut_slice(&self.attributes)) |*entry| {
                _ = &entry;
                _ = (entry.*).deinit(allocator);
            }
            _ = allocator.free(self.attributes);
            _ = self.value.deinit(allocator);
            _ = allocator.destroy(self.value);
    }
};

